function openAsk(text=''){if(!canPost())return;editor={kind:'ask',photos:[]};editorDirty=false;showDialog('Pedir indicação',`${field('ask-input','Sua pergunta',text,'type="textarea" rows="3" required minlength="8" maxlength="300" supporting-text="Inclua o que você precisa e o bairro, se fizer diferença."')}<div id="ask-similar"></div><p class="form-note">Sua pergunta aparece para a comunidade de ${esc(state.homeCity)}.</p>`,`${btn('Cancelar','close-dialog','','text')}${btn('Publicar pergunta','submit-ask','','filled','send')}`,'editor');updateSimilar();}
function updateSimilar(){const text=$('#ask-input')?.value||'',target=$('#ask-similar');if(!target)return;const terms=queryTerms(text);if(terms.length<1){target.innerHTML='';return;}const qs=cityAsks().filter(q=>q.status==='ok'&&matches(terms.slice(0,3).join(' '),q.q,q.keywords||[])).slice(0,2);target.innerHTML=qs.length?`<h3 style="margin-bottom:10px">Uma resposta já pode ajudar</h3><div class="list">${qs.map(questionRow).join('')}</div>`:'<p class="form-note">Nenhuma pergunta resolvida com esses termos. Sua pergunta pode ajudar a próxima família.</p>';}
async function submitAsk(){if(!canPost()||!validFields(['ask-input']))return;const text=$('#ask-input').value.trim();if(text.length<8||queryTerms(text).length<2){notify('Escreva uma pergunta com um pouco mais de contexto.','error');return;}const id=uid('q');const ok=mutate(()=>{state.asks.unshift({id,q:text,city:state.homeCity,who:state.profile.name,ini:initals(state.profile.name),mine:true,topic:state.homeCity,ctx:'Pergunta de um membro da cidade',status:'open',when:'agora',answers:[],createdAt:Date.now()});},{redraw:false});if(ok){await closeDialog(true);navigate('pergunta',id);notify('Pergunta publicada');}}
